ALTER TABLE public.mygrowth_trainings DROP CONSTRAINT mygrowth_trainings_session_kind_check;
ALTER TABLE public.mygrowth_trainings ADD CONSTRAINT mygrowth_trainings_session_kind_check CHECK(session_kind IN ('education','field_coaching','manager_coaching'));
CREATE OR REPLACE FUNCTION public.mygrowth_manager_scope(_tenant uuid,_branch uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.mygrowth_has_branch_role(_branch,'store_manager') AND EXISTS(SELECT 1 FROM public.mygrowth_staff_registry s WHERE s.user_id=auth.uid() AND s.tenant_id=_tenant AND s.branch_id=_branch) $$;
CREATE OR REPLACE FUNCTION public.mygrowth_session_scope(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.mygrowth_trainings t WHERE t.id=_id AND CASE WHEN t.session_kind='manager_coaching' THEN t.trainer_id=auth.uid() AND public.mygrowth_manager_scope(t.tenant_id,t.branch_id) ELSE public.mygrowth_training_scope(t.tenant_id,t.branch_id) END) $$;
CREATE TABLE public.mygrowth_manager_coaching (training_id uuid PRIMARY KEY REFERENCES public.mygrowth_trainings(id), observation text, feedback text NOT NULL CHECK(length(btrim(feedback)) BETWEEN 1 AND 5000), next_action text, original_language text NOT NULL CHECK(original_language IN ('ko','en','ja','zh','yue')), CHECK(length(coalesce(observation,''))<=5000 AND length(coalesce(next_action,''))<=5000));
GRANT SELECT ON public.mygrowth_manager_coaching TO authenticated;
GRANT ALL ON public.mygrowth_manager_coaching TO service_role;
ALTER TABLE public.mygrowth_manager_coaching ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Manager own scoped notes" ON public.mygrowth_manager_coaching FOR SELECT TO authenticated USING(public.mygrowth_session_scope(training_id));
ALTER POLICY "Authorized training managers read" ON public.mygrowth_trainings USING(public.mygrowth_session_scope(id));
ALTER POLICY "Authorized training managers read targets" ON public.mygrowth_training_targets USING(public.mygrowth_session_scope(training_id) AND EXISTS(SELECT 1 FROM public.mygrowth_trainings t WHERE t.id=training_id AND t.tenant_id=mygrowth_training_targets.tenant_id AND t.branch_id=mygrowth_training_targets.branch_id));
ALTER POLICY "Scoped attendance history" ON public.mygrowth_training_attendance_audit USING(public.mygrowth_session_scope(training_id));
CREATE OR REPLACE FUNCTION public.mygrowth_manager_directory() RETURNS TABLE(user_id uuid,full_name text,tenant_id uuid,branch_id uuid,branch_name text,is_trainer boolean) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT s.user_id,coalesce(p.full_name,'이름 미등록'),s.tenant_id,s.branch_id,d.name,(s.user_id=auth.uid()) FROM public.mygrowth_staff_registry s JOIN public.profiles p ON p.user_id=s.user_id JOIN public.departments d ON d.id=s.branch_id WHERE s.active AND p.tenant_id=s.tenant_id AND p.department_id=s.branch_id AND public.mygrowth_manager_scope(s.tenant_id,s.branch_id) ORDER BY p.full_name $$;
CREATE OR REPLACE FUNCTION public.mygrowth_create_manager_coaching(_request_id uuid,_branch_id uuid,_trainer_id uuid,_title text,_training_date date,_location text,_planned_minutes integer,_actual_minutes integer,_observation text,_feedback text,_next_action text,_original_language text,_target_ids uuid[]) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE s public.mygrowth_staff_registry%ROWTYPE; existing public.mygrowth_trainings%ROWTYPE; targets uuid[]; payload jsonb; result uuid; notes text;
BEGIN
 IF NOT public.is_mygrowth_reviewer() OR _trainer_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION '담당 매니저만 기록할 수 있습니다.' USING ERRCODE='42501'; END IF;
 SELECT * INTO s FROM public.mygrowth_staff_registry WHERE user_id=auth.uid() FOR SHARE;
 IF NOT FOUND OR NOT public.mygrowth_manager_scope(s.tenant_id,_branch_id) OR s.branch_id IS DISTINCT FROM _branch_id THEN RAISE EXCEPTION '담당 지점이 아닙니다.' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.mygrowth_assignments a JOIN public.profiles p ON p.user_id=a.user_id JOIN public.mygrowth_reviewers r ON r.user_id=a.user_id WHERE a.user_id=auth.uid() AND a.role='store_manager' AND a.active AND a.tenant_id=s.tenant_id AND a.branch_id=s.branch_id AND p.tenant_id=s.tenant_id AND p.department_id=s.branch_id FOR SHARE OF a,p,r;
 IF NOT FOUND THEN RAISE EXCEPTION '매니저 지정 상태를 확인해 주십시오.' USING ERRCODE='42501'; END IF;
 IF _request_id IS NULL OR nullif(btrim(_title),'') IS NULL OR length(_title)>200 OR _training_date IS NULL OR nullif(btrim(_location),'') IS NULL OR length(_location)>300 OR _planned_minutes IS NULL OR _planned_minutes<=0 OR _actual_minutes<0 OR nullif(btrim(_feedback),'') IS NULL OR length(_feedback)>5000 OR length(coalesce(_observation,''))>5000 OR length(coalesce(_next_action,''))>5000 OR _original_language IS NULL OR _original_language NOT IN ('ko','en','ja','zh','yue') OR coalesce(cardinality(_target_ids),0)=0 OR array_position(_target_ids,NULL) IS NOT NULL THEN RAISE EXCEPTION '필수 입력을 확인해 주십시오.' USING ERRCODE='22023'; END IF;
 SELECT array_agg(DISTINCT u ORDER BY u) INTO targets FROM unnest(_target_ids) u;
 PERFORM 1 FROM public.mygrowth_staff_registry x JOIN public.profiles p ON p.user_id=x.user_id WHERE x.user_id=ANY(targets) FOR SHARE OF x,p;
 IF (SELECT count(*) FROM public.mygrowth_staff_registry x JOIN public.profiles p ON p.user_id=x.user_id WHERE x.user_id=ANY(targets) AND x.active AND x.tenant_id=s.tenant_id AND x.branch_id=s.branch_id AND p.tenant_id=x.tenant_id AND p.department_id=x.branch_id)<>cardinality(targets) THEN RAISE EXCEPTION '담당 지점의 재직 직원만 선택할 수 있습니다.' USING ERRCODE='42501'; END IF;
 notes=concat_ws(E'\n\n',CASE WHEN nullif(btrim(_observation),'') IS NOT NULL THEN '관찰: '||btrim(_observation) END,'매니저 피드백: '||btrim(_feedback),CASE WHEN nullif(btrim(_next_action),'') IS NOT NULL THEN '다음 실행: '||btrim(_next_action) END);
 payload=jsonb_build_object('branch',_branch_id,'trainer',_trainer_id,'title',btrim(_title),'date',_training_date,'location',btrim(_location),'planned',_planned_minutes,'actual',_actual_minutes,'observation',nullif(btrim(_observation),''),'feedback',btrim(_feedback),'next',nullif(btrim(_next_action),''),'language',_original_language,'targets',targets);
 PERFORM pg_advisory_xact_lock(hashtextextended(auth.uid()::text||_request_id::text,0));
 SELECT * INTO existing FROM public.mygrowth_trainings WHERE created_by=auth.uid() AND request_id=_request_id;
 IF FOUND THEN
 IF existing.session_kind<>'manager_coaching' OR existing.request_payload IS DISTINCT FROM payload THEN RAISE EXCEPTION '같은 요청으로 다른 기록을 저장할 수 없습니다.' USING ERRCODE='22023'; END IF;
 RETURN existing.id;
 END IF;
 INSERT INTO public.mygrowth_trainings(tenant_id,branch_id,title,training_type,training_date,location,trainer_id,planned_minutes,actual_minutes,summary,created_by,request_id,request_payload,session_kind) VALUES(s.tenant_id,s.branch_id,btrim(_title),'매니저 코칭',_training_date,btrim(_location),auth.uid(),_planned_minutes,_actual_minutes,notes,auth.uid(),_request_id,payload,'manager_coaching') RETURNING id INTO result;
 INSERT INTO public.mygrowth_training_targets(training_id,user_id,tenant_id,branch_id) SELECT result,u,s.tenant_id,s.branch_id FROM unnest(targets) u;
 INSERT INTO public.mygrowth_manager_coaching(training_id,observation,feedback,next_action,original_language) VALUES(result,nullif(btrim(_observation),''),btrim(_feedback),nullif(btrim(_next_action),''),_original_language);
 RETURN result;
END $$;
CREATE OR REPLACE FUNCTION public.mygrowth_manager_coaching_list() RETURNS TABLE(id uuid,title text,training_type text,training_date date,location text,trainer_name text,branch_name text,planned_minutes integer,actual_minutes integer,summary text,target_count bigint,created_at timestamptz,original_language text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT t.id,t.title,t.training_type,t.training_date,t.location,coalesce(p.full_name,'이름 미등록'),d.name,t.planned_minutes,t.actual_minutes,t.summary,(SELECT count(*) FROM public.mygrowth_training_targets x WHERE x.training_id=t.id),t.created_at,c.original_language FROM public.mygrowth_trainings t JOIN public.mygrowth_manager_coaching c ON c.training_id=t.id JOIN public.departments d ON d.id=t.branch_id LEFT JOIN public.profiles p ON p.user_id=t.trainer_id WHERE t.session_kind='manager_coaching' AND public.mygrowth_session_scope(t.id) ORDER BY t.training_date DESC,t.created_at DESC $$;
CREATE OR REPLACE FUNCTION public.mygrowth_attendance_save(_training_id uuid,_attended_ids uuid[],_expected_version integer) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE t public.mygrowth_trainings%ROWTYPE; chosen uuid[]; previous uuid[];
BEGIN
 IF NOT public.is_mygrowth_reviewer() THEN RAISE EXCEPTION '검수 권한이 없습니다.' USING ERRCODE='42501'; END IF;
 SELECT * INTO t FROM public.mygrowth_trainings WHERE id=_training_id FOR UPDATE;
 IF NOT FOUND OR NOT public.mygrowth_session_scope(t.id) THEN RAISE EXCEPTION '담당 범위가 아닙니다.' USING ERRCODE='42501'; END IF;
 IF _expected_version IS NULL OR _attended_ids IS NULL OR array_position(_attended_ids,NULL) IS NOT NULL THEN RAISE EXCEPTION '참석 입력을 확인해 주십시오.' USING ERRCODE='22023'; END IF;
 IF t.attendance_version<>_expected_version THEN RAISE EXCEPTION '참석 내역이 변경되었습니다. 최신 내역을 다시 확인해 주십시오.' USING ERRCODE='40001'; END IF;
 SELECT coalesce(array_agg(DISTINCT u ORDER BY u),ARRAY[]::uuid[]) INTO chosen FROM unnest(_attended_ids) u;
 PERFORM 1 FROM public.mygrowth_training_targets WHERE training_id=t.id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM unnest(chosen) u WHERE NOT EXISTS(SELECT 1 FROM public.mygrowth_training_targets x WHERE x.training_id=t.id AND x.user_id=u AND x.tenant_id=t.tenant_id AND x.branch_id=t.branch_id)) THEN RAISE EXCEPTION '등록된 참석 대상만 선택할 수 있습니다.' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.mygrowth_staff_registry s JOIN public.profiles p ON p.user_id=s.user_id WHERE s.user_id=ANY(chosen) FOR SHARE OF s,p;
 IF (SELECT count(*) FROM public.mygrowth_staff_registry s JOIN public.profiles p ON p.user_id=s.user_id WHERE s.user_id=ANY(chosen) AND s.active AND s.tenant_id=t.tenant_id AND s.branch_id=t.branch_id AND p.tenant_id=s.tenant_id AND p.department_id=s.branch_id)<>cardinality(chosen) THEN RAISE EXCEPTION '현재 지점의 재직 직원만 참석 등록할 수 있습니다.' USING ERRCODE='42501'; END IF;
 SELECT coalesce(array_agg(user_id ORDER BY user_id),ARRAY[]::uuid[]) INTO previous FROM public.mygrowth_training_targets WHERE training_id=t.id AND attendance_status='attended';
 IF t.attendance_version>0 AND previous=chosen THEN RETURN t.attendance_version; END IF;
 UPDATE public.mygrowth_training_targets SET attendance_status=CASE WHEN user_id=ANY(chosen) THEN 'attended' ELSE 'absent' END WHERE training_id=t.id;
 UPDATE public.mygrowth_trainings SET attendance_version=attendance_version+1,attendance_updated_at=now(),attendance_updated_by=auth.uid() WHERE id=t.id RETURNING attendance_version INTO t.attendance_version;
 INSERT INTO public.mygrowth_training_attendance_audit(training_id,version,changed_by,before_attendees,after_attendees) VALUES(t.id,t.attendance_version,auth.uid(),previous,chosen);
 RETURN t.attendance_version;
END $$;
CREATE OR REPLACE FUNCTION public.mygrowth_attendance_detail(_training_id uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('version',t.attendance_version,'updated_at',t.attendance_updated_at,'people',coalesce((SELECT jsonb_agg(jsonb_build_object('user_id',x.user_id,'full_name',coalesce(p.full_name,'이름 미등록'),'status',x.attendance_status) ORDER BY p.full_name,x.user_id) FROM public.mygrowth_training_targets x LEFT JOIN public.profiles p ON p.user_id=x.user_id WHERE x.training_id=t.id),'[]'::jsonb),'history',coalesce((SELECT jsonb_agg(jsonb_build_object('version',a.version,'changed_at',a.changed_at,'changed_by',coalesce(p.full_name,'이름 미등록'),'attended_count',cardinality(a.after_attendees)) ORDER BY a.version DESC) FROM public.mygrowth_training_attendance_audit a LEFT JOIN public.profiles p ON p.user_id=a.changed_by WHERE a.training_id=t.id),'[]'::jsonb)) FROM public.mygrowth_trainings t WHERE t.id=_training_id AND public.mygrowth_session_scope(t.id) $$;
CREATE OR REPLACE FUNCTION public.mygrowth_training_attendees(_training_id uuid) RETURNS TABLE(user_id uuid,full_name text,status text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT x.user_id,coalesce(p.full_name,'이름 미등록'),x.attendance_status FROM public.mygrowth_training_targets x JOIN public.mygrowth_trainings t ON t.id=x.training_id LEFT JOIN public.profiles p ON p.user_id=x.user_id WHERE t.id=_training_id AND public.mygrowth_session_scope(t.id) ORDER BY p.full_name $$;
CREATE OR REPLACE FUNCTION public.mygrowth_learning_list() RETURNS TABLE(feed_key text,record_type text,title text,detail text,occurred_on date,status text,planned_minutes integer,actual_minutes integer,branch_name text,progress numeric,completion_count integer) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
WITH own_rows AS (
 SELECT 'record:'||r.id::text AS feed_key,r.record_type,r.title,r.detail,r.occurred_on,r.status,r.planned_minutes,r.actual_minutes,d.name AS branch_name,NULL::numeric AS progress,NULL::integer AS completion_count FROM public.mygrowth_records r LEFT JOIN public.departments d ON d.id=r.branch_id WHERE public.is_mygrowth_reviewer() AND r.user_id=auth.uid() AND r.source_table NOT IN ('mygrowth_trainings','mygrowth_field_coaching','mygrowth_manager_coaching','enrollments')
 UNION ALL
 SELECT 'elearning:'||e.id::text,'elearning',c.title,NULL,coalesce((e.completed_at AT TIME ZONE 'Asia/Seoul')::date,(e.enrolled_at AT TIME ZONE 'Asia/Seoul')::date),CASE WHEN e.completed_at IS NOT NULL THEN 'done' WHEN e.status::text='approved' THEN 'in_progress' ELSE 'scheduled' END,(c.estimated_duration_hours*60)::integer,NULL,NULL,e.progress,e.completion_count FROM public.enrollments e JOIN public.courses c ON c.id=e.course_id WHERE public.is_mygrowth_reviewer() AND e.user_id=auth.uid()
 UNION ALL
 SELECT 'attendance:'||t.id::text,CASE WHEN t.session_kind='manager_coaching' THEN 'manager_coaching' WHEN t.session_kind='field_coaching' THEN 'field_coaching' ELSE 'offline_training' END,t.title,t.summary,t.training_date,'attended',t.planned_minutes,t.actual_minutes,d.name,NULL,NULL FROM public.mygrowth_training_targets x JOIN public.mygrowth_trainings t ON t.id=x.training_id JOIN public.departments d ON d.id=t.branch_id WHERE public.is_mygrowth_reviewer() AND x.user_id=auth.uid() AND x.attendance_status='attended' AND t.attendance_version>0 AND x.tenant_id=t.tenant_id AND x.branch_id=t.branch_id
 UNION ALL
 SELECT 'event:'||v.id::text,CASE v.event_type WHEN 'training' THEN 'offline_training' WHEN 'coaching' THEN 'coaching' ELSE v.event_type END,v.title,v.detail,v.occurred_on,v.status,NULL,NULL,NULL,NULL,NULL FROM public.mygrowth_events v WHERE public.is_mygrowth_reviewer() AND v.user_id=auth.uid() AND NOT EXISTS(SELECT 1 FROM public.mygrowth_records r WHERE r.user_id=auth.uid() AND r.source_table='mygrowth_events' AND r.source_id=v.id)
) SELECT * FROM own_rows ORDER BY occurred_on DESC,feed_key;
$$;
REVOKE ALL ON FUNCTION public.mygrowth_manager_scope(uuid,uuid),public.mygrowth_session_scope(uuid),public.mygrowth_manager_directory(),public.mygrowth_create_manager_coaching(uuid,uuid,uuid,text,date,text,integer,integer,text,text,text,text,uuid[]),public.mygrowth_manager_coaching_list() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.mygrowth_manager_scope(uuid,uuid),public.mygrowth_session_scope(uuid),public.mygrowth_manager_directory(),public.mygrowth_create_manager_coaching(uuid,uuid,uuid,text,date,text,integer,integer,text,text,text,text,uuid[]),public.mygrowth_manager_coaching_list() TO authenticated,service_role;